function armoryImage(value){const image=String(value||'');if(!image)return'';if(/^https?:|^data:/.test(image))return image;if(image.startsWith('nui://'))return image.replace(/^nui:\/\/([^/]+)\//,'https://cfx-nui-$1/');if(image.startsWith('web/'))return`https://cfx-nui-cm-weapons/${image}`;if(image.startsWith('images/'))return`https://cfx-nui-cm-weapons/web/${image}`;return`https://cfx-nui-cm-items/ui/images/${image}`}
