 const d=s.data||{},p=dashboardPresentation(),memberCount=Number(d.memberCount??((d.onlineMembers||0)+(d.offlineMembers||0))),score=Math.max(0,Number(d.profit?.activityScore||0)),rep=Math.min(100,score),bonus=d.canIssueBonus?`<section class="dashboard-command"><div><p class="eyebrow">GANG ACCOUNT</p><h3>Member Recognition Bonus</h3><p>Reward an online gang member standing nearby. The payment comes only from the shared gang account.</p></div><button id="issue-gang-bonus">ISSUE NEARBY BONUS</button></section>`:'';
