  <section class="v6-banner"><div class="v6-banner-mark">${esc(p.short||'CM')}</div><div class="v6-banner-copy"><p class="eyebrow">GANG ORGANIZATION</p><h2>${esc(d.gang?.displayName||'Gang')} <span class="v6-tier">TIER ${Number(d.member?.tier||0)}</span></h2><p class="v6-banner-sub">${esc(d.member?.rankName||'Member')} · CID ${esc(d.member?.characterId||'—')}</p></div><div class="v6-rep"><div class="v6-rep-head"><span>ACTIVITY / REPUTATION</span><span>${score.toLocaleString()} PTS · THIS CYCLE</span></div><div class="v6-rep-track"><i style="width:${rep}%"></i></div></div></section>
