 set('info-player-name',player.toUpperCase());set('info-rank',String(d.member?.rankName||'Member').toUpperCase());set('info-leader',String(d.leaderName||'Unassigned').toUpperCase());set('info-profit',`$${Number(d.profit?.pendingAmount||0).toLocaleString()}`);set('info-bottom-name',player);set('info-bottom-rank',`${d.member?.rankName||'Member'} · ${d.gang?.displayName||'Gang'} · Tier ${Number(d.member?.tier||0)}`);
 document.querySelectorAll('[data-dashboard-nav]').forEach(btn=>{const page=btn.dataset.dashboardNav;btn.hidden=!management.includes(page)||!allow(page);btn.onclick=()=>{s.page=page;render()}});
