// Dashboard v9 ranks: show a clean hierarchy first and reveal permissions only while editing.
function rankLevel(tier,isLeader=false){const value=Number(tier||0);if(isLeader||value>=100)return 10;if(value>=10)return Math.max(1,Math.min(9,Math.round(value/10)));return Math.max(1,Math.min(9,Math.round(value)||1))}
function rankPermissionLabel(key){return String(key||'').replace(/^gang\./,'').replaceAll('_',' ')}
function rankEditorMarkup(){
 const d=s.data||{},editor=s.rankEditor;if(!editor)return '';
 const canPermissions=has('gang.manage_permissions'),catalog=(d.permissionCatalog||[]).filter(item=>has(item.key)),selected=editor.permissions||{};
 return `<section class="v9-rank-editor"><header><div><p class="eyebrow">${editor.mode==='create'?'NEW HIERARCHY LEVEL':'EDIT HIERARCHY LEVEL'}</p><h3>${editor.mode==='create'?'Add Rank':esc(editor.name)}</h3></div><button type="button" class="quiet" id="rank-editor-cancel">CANCEL</button></header><div class="v9-rank-fields"><label><span>RANK NAME</span><input id="rank-editor-name" maxlength="48" value="${esc(editor.name||'')}" placeholder="Rank name"></label><label><span>LEVEL</span><select id="rank-editor-level">${Array.from({length:9},(_,i)=>i+1).map(level=>`<option value="${level}" ${level===Number(editor.level)?'selected':''}>Level ${level}</option>`).join('')}</select></label></div>${canPermissions?`<div class="v9-permission-heading"><div><strong>PERMISSIONS</strong><span>Only permissions available to your rank can be assigned.</span></div><button type="button" class="quiet" id="rank-permissions-clear">CLEAR ALL</button></div><div class="v9-permission-grid">${catalog.map(item=>`<label><input type="checkbox" data-rank-permission="${esc(item.key)}" ${selected[item.key]?'checked':''}><span>${esc(rankPermissionLabel(item.key))}</span></label>`).join('')}</div>`:'<p class="muted">You can edit this rank name and level. Permission access requires Manage Permissions.</p>'}<footer><button type="button" id="rank-editor-save">${editor.mode==='create'?'CREATE RANK':'SAVE CHANGES'}</button>${editor.mode==='update'?'<button type="button" class="danger" id="rank-editor-delete">DELETE RANK</button>':''}</footer></section>`;
}
function ranksPageV9(){
 const d=s.data||{},canManage=has('gang.manage_ranks'),rows=(d.ranks||[]).slice().sort((a,b)=>Number(b.tier)-Number(a.tier));
 return `<section class="v9-ranks"><header class="v9-ranks-heading"><div><p class="eyebrow">HIERARCHY</p><h2>Ranks &amp; Access</h2><p>Ranks use levels 1 to 10. Level 10 is reserved for the gang leader.</p></div>${canManage?'<button type="button" id="rank-add">+ ADD RANK</button>':''}</header>${rankEditorMarkup()}<div class="v9-rank-list">${rows.map(rank=>{const count=(d.members||[]).filter(member=>Number(member.rankId)===Number(rank.id)).length,permissionCount=Object.values(rank.permissions||{}).filter(Boolean).length;return `<article class="v9-rank-card ${rank.isLeaderRank?'leader':''}"><div class="v9-level"><small>LEVEL</small><strong>${rankLevel(rank.tier,rank.isLeaderRank)}</strong></div><div class="v9-rank-copy"><div><h3>${esc(rank.name)}</h3>${rank.isLeaderRank?'<span>LEADER</span>':''}</div><p>${count} member${count===1?'':'s'} &middot; ${permissionCount} permission${permissionCount===1?'':'s'}</p></div>${canManage&&!rank.isLeaderRank?`<button type="button" data-rank-open="${rank.id}">EDIT RANK</button>`:'<span class="v9-protected">PROTECTED</span>'}</article>`}).join('')||'<div class="empty">No ranks configured.</div>'}</div></section>`;
}
const rankBodyV9Base=body;
body=function(){if(s.mode==='dashboard'&&s.page==='ranks')return ranksPageV9();return rankBodyV9Base()};
const rankBindV9Base=bind;
bind=function(){
 rankBindV9Base();if(s.mode!=='dashboard'||s.page!=='ranks')return;
 document.getElementById('rank-add')?.addEventListener('click',()=>{s.rankEditor={mode:'create',name:'',level:1,permissions:{}};render()});
 document.querySelectorAll('[data-rank-open]').forEach(button=>button.addEventListener('click',()=>{const rank=(s.data.ranks||[]).find(item=>Number(item.id)===Number(button.dataset.rankOpen));if(!rank)return;s.rankEditor={mode:'update',rankId:rank.id,name:rank.name,level:rankLevel(rank.tier),permissions:{...(rank.permissions||{})}};render()}));
 document.getElementById('rank-editor-cancel')?.addEventListener('click',()=>{s.rankEditor=null;render()});
 document.getElementById('rank-permissions-clear')?.addEventListener('click',()=>document.querySelectorAll('[data-rank-permission]').forEach(input=>input.checked=false));
 document.getElementById('rank-editor-save')?.addEventListener('click',async()=>{const name=document.getElementById('rank-editor-name')?.value.trim()||'',level=Number(document.getElementById('rank-editor-level')?.value),permissions={...(s.rankEditor?.permissions||{})};document.querySelectorAll('[data-rank-permission]').forEach(input=>permissions[input.dataset.rankPermission]=input.checked);if(!name)return toast('Enter a rank name.',true);const payload={action:s.rankEditor.mode==='create'?'create':'update',rankId:s.rankEditor.rankId,name,level,permissions};const result=await call('rankAction',payload,s.rankEditor.mode==='create'?'Rank created.':'Rank updated.');if(result.ok){s.rankEditor=null;await refresh()}});
 document.getElementById('rank-editor-delete')?.addEventListener('click',async()=>{if(!await gangConfirm('Delete this unused rank?'))return;const result=await call('rankAction',{action:'delete',rankId:s.rankEditor.rankId},'Rank deleted.');if(result.ok){s.rankEditor=null;await refresh()}});
};
const rankRenderV9Base=render;
render=function(){if(s.page!=='ranks')s.rankEditor=null;rankRenderV9Base();const d=s.data||{},level=rankLevel(d.member?.tier);const rail=document.getElementById('rail-player-rank'),bottom=document.getElementById('info-bottom-rank');if(rail)rail.textContent=`${d.member?.rankName||'Member'} · Level ${level}`;if(bottom)bottom.textContent=`${d.member?.rankName||'Member'} · ${d.gang?.displayName||'Gang'} · Level ${level}`};

// Dashboard v10 blacklist: add offline or online characters by persistent character ID.
function blacklistPageV10(){
 const canAdd=has('gang.blacklist');
 return `<section class="v10-blacklist"><header><div><p class="eyebrow">MEMBERSHIP CONTROL</p><h2>Blacklist</h2><p>Block a character from joining this gang using their persistent character ID.</p></div><button type="button" class="quiet" id="blacklist-refresh">REFRESH</button></header>${canAdd?'<section class="v10-blacklist-add"><label><span>CHARACTER ID</span><input id="blacklist-character-id" inputmode="numeric" maxlength="64" placeholder="Enter character ID"></label><label><span>REASON</span><input id="blacklist-reason" maxlength="255" placeholder="Reason for blacklist"></label><button type="button" id="blacklist-add">ADD TO BLACKLIST</button></section>':''}<div id="blacklist-items" class="v10-blacklist-list"><div class="empty">Loading blacklist…</div></div></section>`;
}
const blacklistBodyV10Base=body;
body=function(){if(s.mode==='dashboard'&&s.page==='blacklist')return blacklistPageV10();return blacklistBodyV10Base()};
async function loadBlacklistV10(){
 const box=document.getElementById('blacklist-items');if(!box)return;
 const result=await post('blacklistAction',{action:'list'});if(!result?.ok){box.innerHTML=`<div class="empty">${esc(why(result?.reason))}</div>`;return}
 const entries=result.entries||[];box.innerHTML=entries.map(entry=>`<article class="v10-blacklist-row"><div><strong>${esc(entry.name||`Character ${entry.characterId}`)}</strong><span>CID ${esc(entry.characterId)} &middot; ${esc(entry.reason||'No reason supplied')}</span></div>${has('gang.manage_blacklist')?`<button type="button" class="danger" data-blacklist-remove="${esc(entry.characterId)}">REMOVE</button>`:''}</article>`).join('')||'<div class="empty">No blacklisted characters.</div>';
 box.querySelectorAll('[data-blacklist-remove]').forEach(button=>button.addEventListener('click',async()=>{if(!await gangConfirm(`Remove CID ${button.dataset.blacklistRemove} from the blacklist?`))return;const response=await call('blacklistAction',{action:'remove',targetCharacterId:button.dataset.blacklistRemove},'Removed from blacklist.');if(response.ok)loadBlacklistV10()}));
}
const blacklistBindV10Base=bind;
bind=function(){blacklistBindV10Base();if(s.mode!=='dashboard'||s.page!=='blacklist')return;document.getElementById('blacklist-refresh')?.addEventListener('click',loadBlacklistV10);document.getElementById('blacklist-add')?.addEventListener('click',async()=>{const targetCharacterId=String(document.getElementById('blacklist-character-id')?.value||'').trim(),reason=String(document.getElementById('blacklist-reason')?.value||'').trim();if(!/^\d+$/.test(targetCharacterId))return toast('Enter a valid character ID.',true);if(!await gangConfirm(`Blacklist character CID ${targetCharacterId}?`))return;const result=await call('blacklistAction',{action:'add',targetCharacterId,reason},'Character blacklisted.');if(result.ok){document.getElementById('blacklist-character-id').value='';document.getElementById('blacklist-reason').value='';loadBlacklistV10()}});loadBlacklistV10()};

// Dashboard v11 quick coordination actions replace the removed Meeting & Map page.
function bindQuickCoordinationV11(){
 const meeting=document.getElementById('quick-set-meeting'),tracking=document.getElementById('quick-toggle-members');
 if(meeting){meeting.hidden=!has('gang.set_meeting_point');meeting.onclick=async()=>{if(!await gangConfirm('Set the gang meeting point at your current location?'))return;await call('coordinationAction',{action:'meeting'},'Gang meeting point set.')}}
 if(tracking){const permitted=has('gang.view_map');tracking.hidden=!permitted;tracking.textContent=s.quickTracking?'HIDE GANG MEMBERS':'SHOW GANG MEMBERS';tracking.onclick=async()=>{const enabled=!s.quickTracking,message=enabled?'Display online gang members on your map?':'Hide gang members from your map?';if(!await gangConfirm(message))return;const result=await call('coordinationAction',{action:'tracking',enabled},enabled?'Gang members are now displayed on the map.':'Gang members hidden from the map.');if(result.ok){s.quickTracking=result.tracking===true;tracking.textContent=s.quickTracking?'HIDE GANG MEMBERS':'SHOW GANG MEMBERS'}};if(permitted&&!s.coordinationLoaded){s.coordinationLoaded=true;post('coordinationAction',{action:'status'}).then(result=>{if(!result?.ok)return;s.quickTracking=result.tracking===true;const current=document.getElementById('quick-toggle-members');if(current)current.textContent=s.quickTracking?'HIDE GANG MEMBERS':'SHOW GANG MEMBERS'})}}
}
const quickRenderV11Base=render;
render=function(){quickRenderV11Base();if(s.mode==='dashboard')bindQuickCoordinationV11()};

// Dashboard v12 script-configured gang events.
function eventTimeV12(epoch){return new Intl.DateTimeFormat(undefined,{weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(Number(epoch)*1000))}
function eventsPageV12(){return `<section class="v12-events"><header><div><p class="eyebrow">GANG SCHEDULE</p><h2>Events</h2><p>Live and upcoming events configured by the server script.</p></div><button type="button" class="quiet" id="events-refresh">REFRESH</button></header><div class="v12-event-section"><div class="v12-event-title"><span class="live-dot"></span><strong>ONGOING EVENTS</strong></div><div id="events-ongoing" class="v12-event-list"><div class="empty">Loading events…</div></div></div><div class="v12-event-section"><div class="v12-event-title"><span></span><strong>UPCOMING EVENTS</strong></div><div id="events-upcoming" class="v12-event-list"><div class="empty">Loading events…</div></div></div></section>`}
const eventsBodyV12Base=body;
body=function(){if(s.mode==='dashboard'&&s.page==='events')return eventsPageV12();return eventsBodyV12Base()};
function eventCardV12(event){return `<article class="v12-event-card ${event.status==='ongoing'?'ongoing':''}"><div class="v12-event-date"><small>${event.status==='ongoing'?'LIVE NOW':'STARTS'}</small><strong>${esc(eventTimeV12(event.startsAt))}</strong></div><div><h3>${esc(event.title)}</h3><p>${esc(event.description||'Gang event')}</p><span>${event.status==='ongoing'?`Ends ${esc(eventTimeV12(event.endsAt))}`:`Duration ${Math.max(1,Math.round((Number(event.endsAt)-Number(event.startsAt))/60))} minutes`}</span></div><b>${event.status.toUpperCase()}</b></article>`}
async function loadEventsV12(){const ongoing=document.getElementById('events-ongoing'),upcoming=document.getElementById('events-upcoming');if(!ongoing||!upcoming)return;const result=await post('loadScriptedEvents');if(!result?.ok){ongoing.innerHTML=`<div class="empty">${esc(why(result?.reason))}</div>`;upcoming.innerHTML='';return}const events=result.events||[],live=events.filter(event=>event.status==='ongoing'),next=events.filter(event=>event.status==='upcoming');ongoing.innerHTML=live.map(eventCardV12).join('')||'<div class="empty">No event is running right now.</div>';upcoming.innerHTML=next.map(eventCardV12).join('')||'<div class="empty">No upcoming events configured.</div>'}
const eventsBindV12Base=bind;
bind=function(){eventsBindV12Base();if(s.mode==='dashboard'&&s.page==='events'){document.getElementById('events-refresh')?.addEventListener('click',loadEventsV12);loadEventsV12()}};

// Reusable gang-event overlay. Server timestamps remain authoritative; this only renders between syncs.
const ge={active:false,everJoined:false,endsAt:0,nextAt:0,duration:0,boundaryDeadline:0,combatExpiresAt:0,feed:[]};
function geClock(value){const n=Math.max(0,Number(value||0)-Math.floor(Date.now()/1000));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function geBanner(text,ms=3500){const el=document.getElementById('ge-banner');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(ge.banner);ge.banner=setTimeout(()=>el.classList.remove('show'),ms)}
function geOpen(data){ge.active=true;ge.everJoined=true;ge.endsAt=Number(data.endsAt||ge.endsAt);ge.duration=Number(data.config?.duration||(Number(data.endsAt||0)-Number(data.liveAt||0))||ge.duration||0);document.body.classList.remove('gang-event-announcement');document.body.classList.add('gang-event')}
function geClose(){ge.active=false;ge.boundaryDeadline=0;ge.combatExpiresAt=0;document.body.classList.remove('gang-event','gang-event-announcement')}
function geAnnouncement(text,ms=6000){if(ge.active)return geBanner(text,ms);document.body.classList.add('gang-event-announcement');geBanner(text,ms);setTimeout(()=>{if(!ge.active)document.body.classList.remove('gang-event-announcement')},ms+250)}
setInterval(()=>{if(!ge.active)return;const now=Date.now()/1000,remaining=Math.max(0,ge.endsAt-now),timer=document.getElementById('ge-timer'),phase=document.getElementById('ge-next'),fill=document.getElementById('ge-progress-fill');if(timer)timer.textContent=geClock(ge.endsAt);if(phase)phase.textContent=ge.nextAt>now?`SUPPLY LANDING ${geClock(ge.nextAt)}`:'FINAL PHASE';if(fill){const duration=Math.max(1,ge.duration||remaining||1);fill.style.width=`${Math.max(0,Math.min(100,remaining/duration*100))}%`}},250);
window.addEventListener('message',e=>{const m=e.data||{},d=m.data||{};if(m.action==='gangEventBoundaryWarning'){ge.boundaryDeadline=Number(d.deadline||0)||Math.floor(Date.now()/1000)+Number(d.seconds||5)}else if(m.action==='gangEventBoundaryReturned'){ge.boundaryDeadline=0;const el=document.getElementById('ge-banner');if(el)el.classList.remove('show')}else if(m.action==='gangEventCombatTag'){ge.combatExpiresAt=d.active===false?0:Number(d.expiresAt||d.untilAt||0)}});
setInterval(()=>{if(!ge.active||!ge.boundaryDeadline)return;const remaining=Math.max(0,Math.ceil(ge.boundaryDeadline-Date.now()/1000)),el=document.getElementById('ge-banner');if(el){el.textContent=`RETURN TO EVENT AREA · ${remaining}`;el.classList.add('show')}},250);
window.addEventListener('message',e=>{const m=e.data||{},d=m.data||{};if(m.action==='gangEventAnnouncement'){ge.endsAt=Number(d.endsAt||0);geAnnouncement(`GANG SUPPLY WAR STARTING · ${d.config?.areaName||'EVENT AREA'} · ${geClock(d.liveAt)}`,6000)}else if(m.action==='gangEventLive'){ge.endsAt=Number(d.endsAt||ge.endsAt);geAnnouncement('GANG SUPPLY WAR LIVE · TRAVEL TO THE EVENT ZONE',5000)}else if(m.action==='gangEventJoined'){geOpen(d);geBanner('GANG SUPPLY WAR LIVE')}else if(m.action==='gangEventLeave'){geClose()}else if(m.action==='gangEventScores'){if(!ge.active)return;document.getElementById('ge-leading').textContent=d.leading?`${String(d.leading.gangId).toUpperCase()} — ${d.leading.score} PTS${d.leading.heat>=8?' · HIGH HEAT':''}`:'--';document.getElementById('ge-top-list').innerHTML=(d.top||[]).map(x=>`<li>${esc(x.name)} [${esc(String(x.gangId).toUpperCase())}] — ${Number(x.kills)}</li>`).join('')}else if(m.action==='gangEventKillFeed'){if(!ge.active)return;const feed=document.getElementById('ge-kill-feed'),row=document.createElement('div');row.textContent=`${d.killer} [${String(d.killerGang).toUpperCase()}] ${d.weapon||'killed'} ${d.victim} [${String(d.victimGang).toUpperCase()}]${d.scored?'':' · NO SCORE'}`;feed.prepend(row);while(feed.children.length>5)feed.lastChild.remove();setTimeout(()=>row.remove(),6000);if([3,5,8].includes(Number(d.streak)))geBanner(d.streak===3?'ON FIRE':d.streak===5?'RAMPAGE':'MOST WANTED')}else if(m.action==='gangDropInbound'){if(!ge.active)return;ge.nextAt=Number(d.landAt);geBanner(d.final?'FINAL HIGH-VALUE SUPPLY INBOUND':'SUPPLY AIRCRAFT INBOUND')}else if(m.action==='gangDropClaim'){if(ge.active)geBanner(d.contested?'SUPPLY DROP — CONTESTED':'SECURING SUPPLY DROP',Number(d.seconds||3)*1000)}else if(m.action==='gangDropClaimed'){if(ge.active)geBanner(`${String(d.gangId).toUpperCase()} SECURED DROP #${d.number}`)}else if(m.action==='gangEventEnded'){if(ge.everJoined){geOpen(d);geBanner(d.cancelled?'SUPPLY WAR CANCELLED':`SUPPLY WAR FINISHED · WINNER ${String(d.winner?.gangId||'NONE').toUpperCase()}`,12000)}}else if(m.action==='gangEventClear'){geClose();ge.everJoined=false;ge.endsAt=0;ge.nextAt=0}});

const gangSearch=document.getElementById('gang-search'),gangSearchItems=document.getElementById('gang-search-items');
function closeGangSearch(){post('closeGangSearch',{})}
window.addEventListener('message',event=>{const message=event.data||{};if(message.action==='gangSearchOpen'){const items=Array.isArray(message.items)?message.items:[];document.body.classList.add('gang-search-open');gangSearch.hidden=false;gangSearchItems.innerHTML=items.length?items.map(item=>`<article class="gang-search-item"><strong>${esc(item.label||item.itemName||'Unknown item')}</strong><small>${esc(item.sourceArea||'Inventory')} · ${esc(item.itemName||'ITEM')}</small><b>x${Math.max(0,Number(item.quantity)||0)}</b></article>`).join(''):'<div class="gang-search-empty">No contraband, weapons or ammunition found.</div>'}else if(message.action==='gangSearchClose'){gangSearch.hidden=true;document.body.classList.remove('gang-search-open')}});
document.getElementById('gang-search-close')?.addEventListener('click',closeGangSearch);
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&gangSearch&&!gangSearch.hidden){event.preventDefault();closeGangSearch()}});

// Supply War presentation inside the existing Gang Dashboard Events section.
function supplyImage(value){return String(value||'').replace(/^nui:\/\/([^/]+)\//,'https://cfx-nui-$1/')}
function supplyStatus(runtime){const state=String(runtime?.state||'IDLE');return state==='IDLE'?'UPCOMING':state==='ENDED'?'COMPLETED':state}
function supplyClock(epoch,serverTime){const seconds=Math.max(0,Number(epoch||0)-Number(serverTime||Math.floor(Date.now()/1000)));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`}
function supplyEventsPage(){return `<section class="v12-events"><header><div><p class="eyebrow">GANG DASHBOARD · EVENTS</p><h2>Events</h2><p>Authoritative event schedule, details and previous results.</p></div><button type="button" class="quiet" id="events-refresh">REFRESH</button></header><div id="supply-war-event" class="supply-war-event"><div class="empty">Loading Supply War…</div></div><div class="v12-event-section"><div class="v12-event-title"><span></span><strong>OTHER GANG EVENTS</strong></div><div id="events-ongoing" class="v12-event-list"></div><div id="events-upcoming" class="v12-event-list"></div></div></section>`}
function closeSupplyResult(){const modal=document.getElementById('supply-result-modal');if(modal)modal.hidden=true;document.body.classList.remove('supply-result-open');if(!document.body.classList.contains('open'))post('closeEventResult')}
function showSupplyResult(response){const result=response?.result||{},event=result.presentation||{},modal=document.getElementById('supply-result-modal'),standings=result.standings||[],title=event.title||'SUPPLY WAR',arsenal=result.eventType==='arsenal_resupply',summary=arsenal?`<dl><div><dt>ARMY SECURED</dt><dd>${Number(result.armyPercent||0)}%</dd></div><div><dt>LOST</dt><dd>${Number(result.lostPercent||0)}%</dd></div></dl>`:'';if(!modal)return;modal.hidden=false;modal.innerHTML=`<article><button id="supply-result-close">ESC</button><img src="${esc(supplyImage(event.image))}" alt="${esc(title)}"><div><small>${esc(title.toUpperCase())} COMPLETE</small><h2>${esc(String(result.winner||standings[0]?.gangId||'NO WINNER').toUpperCase())}</h2><p>WINNER</p>${summary}<ol>${standings.map((row,index)=>`<li><b>${index+1}. ${esc(String(row.gangId||'').toUpperCase())}</b><span>${Number(row.stolenValue||row.score||0)} VALUE</span></li>`).join('')}</ol></div></article>`;document.body.classList.add('supply-result-open');document.getElementById('supply-result-close').onclick=closeSupplyResult}
function renderSupplyWar(result){const box=document.getElementById('supply-war-event');if(!box)return;if(!result?.ok){box.innerHTML=`<div class="empty">${esc(why(result?.reason))}</div>`;return}const event=result.event||{},runtime=result.runtime||{},status=supplyStatus(runtime),image=supplyImage(event.image),deadline=status==='LIVE'?runtime.endsAt:status==='WARMUP'?runtime.liveAt:0,label=status==='LIVE'?'ENDS IN':status==='WARMUP'?'STARTS IN':'NEXT EVENT',time=deadline?supplyClock(deadline,result.serverTime):runtime.nextAt?eventTimeV12(runtime.nextAt):'CALCULATING';box.innerHTML=`<article class="supply-event-card"><img src="${esc(image)}" alt="Supply War"><div><span class="supply-status ${status.toLowerCase()}">${esc(status)}</span><h3>${esc(event.title||'Supply War')}</h3><p>${esc(event.subtitle||'Gang Combat Event')}</p><dl><div><dt>${label}</dt><dd>${esc(time)}</dd></div><div><dt>DURATION</dt><dd>${Math.max(1,Math.round(Number(runtime.duration||1200)/60))} MIN</dd></div></dl><button id="supply-details-open">VIEW DETAILS</button></div></article><article id="supply-details" class="supply-details" hidden><img src="${esc(image)}" alt="Supply War"><div><span class="supply-status ${status.toLowerCase()}">${esc(status)}</span><h3>SUPPLY WAR</h3><p>${esc(event.description||'Fight opposing gangs and secure supply crates.')}</p><div class="supply-detail-grid"><section><small>HOW TO JOIN</small><p>Reach the outer edge of the event zone and press E while the event is live.</p></section><section><small>OBJECTIVE</small><p>Fight opposing gangs and secure supply crates.</p></section><section><small>SUPPLY REWARD</small><p>Configured Gang Armory Package</p></section><section><small>RULES</small><ul>${(event.rules||[]).map(rule=>`<li>${esc(rule)}</li>`).join('')}</ul></section></div></div></article><section class="supply-history"><header><strong>PREVIOUS EVENTS</strong><small>Saved event history</small></header>${(result.history||[]).map(row=>`<button class="supply-history-row" data-supply-history="${esc(row.eventId)}"><b>${esc(String(row.winner||'No winner').toUpperCase())}</b><span>${Number(row.standings?.[0]?.score||0)} PTS</span><time>${row.endedAt?esc(eventTimeV12(row.endedAt)):'—'}</time></button>`).join('')||'<div class="empty">No completed Supply War events yet.</div>'}</section>`;document.getElementById('supply-details-open').onclick=()=>{const details=document.getElementById('supply-details');details.hidden=!details.hidden};box.querySelectorAll('[data-supply-history]').forEach(button=>button.onclick=()=>{const row=(result.history||[]).find(item=>item.eventId===button.dataset.supplyHistory);showSupplyResult({result:{...row,presentation:event}})})}
async function loadSupplyEvents(){const ongoing=document.getElementById('events-ongoing'),upcoming=document.getElementById('events-upcoming');if(!ongoing||!upcoming)return;const [supply,other]=await Promise.all([post('loadSupplyWarPresentation'),post('loadScriptedEvents')]);renderSupplyWar(supply);const events=other?.ok?other.events||[]:[];ongoing.innerHTML=events.filter(event=>event.status==='ongoing').map(eventCardV12).join('');upcoming.innerHTML=events.filter(event=>event.status==='upcoming').map(eventCardV12).join('')}
const supplyBodyBase=body;body=function(){if(s.mode==='dashboard'&&s.page==='events')return supplyEventsPage();return supplyBodyBase()};
const supplyBindBase=bind;bind=function(){supplyBindBase();if(s.mode==='dashboard'&&s.page==='events'){document.getElementById('events-refresh')?.addEventListener('click',loadSupplyEvents);loadSupplyEvents()}};
window.addEventListener('message',event=>{const message=event.data||{};if(message.action==='gangEventQuickResult')showSupplyResult(message.data);if(message.action==='gangEventQuickResultClose'){const modal=document.getElementById('supply-result-modal');if(modal)modal.hidden=true;document.body.classList.remove('supply-result-open')}});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('supply-result-open')){event.preventDefault();event.stopImmediatePropagation();closeSupplyResult()}},true);

// Arsenal Resupply extends the existing Events presentation/history surface.
supplyEventsPage=function(){return `<section class="v12-events"><header><div><p class="eyebrow">GANG DASHBOARD · EVENTS</p><h2>Events</h2><p>Authoritative schedules, event details and permanent results.</p></div><button type="button" class="quiet" id="events-refresh">REFRESH</button></header><div id="arsenal-event" class="supply-war-event"><div class="empty">Loading Arsenal Resupply…</div></div><div id="supply-war-event" class="supply-war-event"><div class="empty">Loading Supply War…</div></div><div class="v12-event-section"><div class="v12-event-title"><span></span><strong>OTHER GANG EVENTS</strong></div><div id="events-ongoing" class="v12-event-list"></div><div id="events-upcoming" class="v12-event-list"></div></div></section>`};
function renderArsenal(result){const box=document.getElementById('arsenal-event');if(!box)return;if(!result?.ok){box.innerHTML=`<div class="empty">${esc(why(result?.reason))}</div>`;return}const event=result.event||{},runtime=result.runtime||{},raw=String(runtime.state||'IDLE'),status=raw==='IDLE'?'UPCOMING':raw==='CONVOY_ACTIVE'||raw==='WAREHOUSE_UNLOADING'?'ACTIVE':raw==='ARMY_PREPARATION'||raw==='WARMUP'?'WARMUP':['COMPLETED','CANCELLED','INTERRUPTED'].includes(raw)?'COMPLETED':raw,image=supplyImage(event.image),next=runtime.nextStartAt?eventTimeV12(runtime.nextStartAt):'NOT SCHEDULED';box.innerHTML=`<article class="supply-event-card"><img src="${esc(image)}" alt="Arsenal Resupply"><div><span class="supply-status ${status.toLowerCase()}">${esc(status)}</span><h3>${esc(event.title||'Arsenal Resupply')}</h3><p>${esc(event.subtitle||'Military Convoy Event')}</p><dl><div><dt>NEXT EVENT</dt><dd>${esc(next)}</dd></div><div><dt>DURATION</dt><dd>${Math.max(1,Math.round(Number(runtime.duration||3600)/60))} MIN</dd></div></dl><button id="arsenal-details-open">VIEW DETAILS</button></div></article><article id="arsenal-details" class="supply-details" hidden><img src="${esc(image)}" alt="Arsenal Resupply"><div><span class="supply-status ${status.toLowerCase()}">${esc(status)}</span><h3>${esc(event.title||'ARSENAL RESUPPLY')}</h3><p>${esc(event.description||'Intercept Army convoy cargo.')}</p><div class="supply-detail-grid"><section><small>OBJECTIVE</small><p>Intercept Army convoy and extract military cargo before Army secures it.</p></section><section><small>ARMY OBJECTIVE</small><p>Transport and secure incoming military stock.</p></section><section><small>RULES</small><ul>${(event.rules||[]).map(rule=>`<li>${esc(rule)}</li>`).join('')}</ul></section></div></div></article><section class="supply-history"><header><strong>ARSENAL HISTORY</strong><small>Events your gang participated in</small></header>${(result.history||[]).map((row,index)=>`<button class="supply-history-row" data-arsenal-history="${index}"><b>${esc(String(row.winner||'No winner').toUpperCase())}</b><span>ARMY ${Number(row.armyPercent||0)}% · LOST ${Number(row.lostPercent||0)}%</span><time>${esc(String(row.status||''))}</time></button>`).join('')||'<div class="empty">No participated Arsenal results yet.</div>'}</section>`;document.getElementById('arsenal-details-open').onclick=()=>{const details=document.getElementById('arsenal-details');details.hidden=!details.hidden};box.querySelectorAll('[data-arsenal-history]').forEach(button=>button.onclick=()=>showSupplyResult({result:(result.history||[])[Number(button.dataset.arsenalHistory)]}))}
loadSupplyEvents=async function(){const ongoing=document.getElementById('events-ongoing'),upcoming=document.getElementById('events-upcoming');if(!ongoing||!upcoming)return;const [arsenal,supply,other]=await Promise.all([post('loadArsenalPresentation'),post('loadSupplyWarPresentation'),post('loadScriptedEvents')]);renderArsenal(arsenal);renderSupplyWar(supply);const events=other?.ok?other.events||[]:[];ongoing.innerHTML=events.filter(event=>event.status==='ongoing').map(eventCardV12).join('');upcoming.innerHTML=events.filter(event=>event.status==='upcoming').map(eventCardV12).join('')};

// Dashboard v15: direct live-data translation of the supplied standalone overview.
function v15ReferenceEvents(){const rows=(s.data?.activity||[]).slice(0,2),defaults=[{action:'Gang event',createdAt:'No date set'},{action:'Schedule event',createdAt:'No date set'}],items=[...(rows.length?rows:defaults),{action:'Schedule event',createdAt:'No date set',newCard:true}].slice(0,3);return items.map((row,index)=>{const name=String(row.action||row.eventType||'Gang event').replaceAll('_',' '),when=row.createdAt||row.created_at||'No date set';return `<article class="v15-event ${row.newCard?'is-new':''}"><div class="v15-event-shot"><span>▧</span><b>${row.newCard?'ADD EVENT':'EVENT SHOT'}</b><small>or browse files</small></div><footer><div><strong>${esc(name)}</strong><span>${esc(when)}</span></div><em>${row.newCard?'NEW':index===0?'LIVE':'OPEN'}</em></footer></article>`}).join('')}
dashboardOverview=function(){const d=s.data||{},p=dashboardPresentation(),members=Number(d.memberCount??((d.onlineMembers||0)+(d.offlineMembers||0))),score=Math.max(0,Number(d.profit?.activityScore||0)),rep=Math.min(100,score),activityCount=Math.max(0,(d.activity||[]).length),leaderIsYou=String(d.leaderName||'').trim().toLowerCase()===String(dashboardMemberName()).trim().toLowerCase(),bonus=d.canIssueBonus?`<section class="v15-bonus"><div><p>GANG ACCOUNT</p><h3>MEMBER RECOGNITION BONUS</h3><span>Reward an online gang member standing nearby. The payment comes only from the shared gang account.</span></div><div><button id="issue-gang-bonus">ISSUE NEARBY BONUS</button><small>BALANCE <b>$${Number(d.profit?.pendingAmount||0).toLocaleString()}</b></small></div></section>`:'';return `<section class="v15-overview"><section class="v15-banner"><div><p>GANG ORGANIZATION</p><h2>${esc(d.gang?.displayName||'Gang')} <span>TIER ${Number(d.member?.tier||0)}</span></h2></div><div class="v15-rep"><label><span>REPUTATION</span><b>${score.toLocaleString()} / 100 · MAX</b></label><i><b style="width:${rep}%"></b></i></div></section><section class="v15-stats"><article><small>LEADER ${leaderIsYou?'<em>YOU</em>':''}</small><strong>${esc(d.leaderName||'Unassigned')}</strong><span>${esc(d.member?.rankName||'Member')} · Tier ${Number(d.member?.tier||0)}</span></article><article><small>MEMBERS <em>ONLINE</em></small><strong>${Number(d.onlineMembers||0)} / ${members}</strong><span>${Number(d.onlineMembers||0)} online · ${Number(d.offlineMembers||0)} offline</span></article><article><small>EVENTS</small><strong>${activityCount}</strong><span>${activityCount?'Live network records':'No active events'}</span></article><article><small>PROFIT <em>0%</em></small><strong>$${Number(d.profit?.pendingAmount||0).toLocaleString()}</strong><span>this cycle</span></article></section>${bonus}<section class="v15-events"><header><span>EVENTS · ${Math.min(3,Math.max(activityCount,2))} ACTIVE</span><button id="v8-open-activity">EVENTS</button></header><div>${v15ReferenceEvents()}</div></section></section>`};

/* v16 reference information rail. */
function v16BindInformationRail(){
 const player=dashboardMemberName(),author=document.getElementById('info-notice-author'),stamp=document.getElementById('info-notice-time');
 if(author)author.textContent=player;
 if(stamp)stamp.textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date());
 const invite=document.getElementById('quick-invite'),leave=document.getElementById('quick-leave-gang');
 if(invite&&!invite.dataset.bound){invite.dataset.bound='1';invite.addEventListener('click',()=>toast('Close the dashboard, face a nearby player, then use the G interaction to invite them.'))}
 if(leave&&!leave.dataset.bound){leave.dataset.bound='1';leave.addEventListener('click',()=>toast('Leaving a gang must be completed through an authorized membership action.',false))}
}
const renderV16Base=render;
render=function(){renderV16Base();if(s.mode==='dashboard')v16BindInformationRail()};
